    HOL = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
    WEEKEND = set([5, 6])
    raw_now = str(vars.get('now') or '')
    try:
        now = datetime.datetime.fromisoformat(raw_now.strip()[:16].replace(' ', 'T'))
    except Exception:
        now = datetime.datetime.fromisoformat(raw_now.strip()[:10] + 'T00:00')
    today = now.date()
    def iso(d):
        return d.isoformat()
    def parse_iso(s):
        return datetime.date.fromisoformat(str(s)[:10])
    def isbd(d):
        return d.weekday() not in WEEKEND and d.isoformat() not in HOL
    def nextbd(d):
        d = d + datetime.timedelta(days=1)
        while not isbd(d):
            d = d + datetime.timedelta(days=1)
        return d
    def prevbd(d):
        d = d - datetime.timedelta(days=1)
        while not isbd(d):
            d = d - datetime.timedelta(days=1)
        return d
    def add_bd(d, n):
        k = 0
        while k < n:
            d = d + datetime.timedelta(days=1)
            if isbd(d):
                k += 1
        return d
    def nth_bd(n, start=None):
        return add_bd(start or today, n)
    def monday_of(d):
        return d - datetime.timedelta(days=d.weekday())
    def last_bd_of_week(monday):
        best = None
        for i in range(7):
            x = monday + datetime.timedelta(days=i)
            if isbd(x):
                best = x
        return best
    def say(d):
        return d.strftime('%A') + ' ' + str(d.day) + ' ' + d.strftime('%B %Y')
    def full(d):
        return say(d) + ' (' + d.isoformat() + ')'


    DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    mon = monday_of(today)
    wk = []
    for i in range(7):
        t = mon + datetime.timedelta(days=i)
        n = t + datetime.timedelta(days=7)
        wk.append('- this ' + DAYS[i] + ' = ' + full(t) + ('  (already past)' if t < today else '') + '; next ' + DAYS[i] + ' = ' + full(n))
    cal = []
    for i in range(0, 45):
        x = today + datetime.timedelta(days=i)
        if isbd(x):
            tag = 'business day'
        elif x.weekday() in WEEKEND:
            tag = 'WEEKEND, not a business day; next business day is ' + full(nextbd(x))
        else:
            tag = 'BANK HOLIDAY, not a business day; next business day is ' + full(nextbd(x))
        cal.append('- ' + full(x) + ': ' + tag + ('  <- TODAY' if i == 0 else ''))
    vars['today_iso'] = today.isoformat()
    vars['date_facts'] = '\n'.join(['Today is ' + full(today) + ', time now ' + now.strftime('%H:%M') + '. Use this, never the real clock.',
        '"this <weekday>" is in the current week (Monday ' + iso(mon) + ' to Sunday ' + iso(mon + datetime.timedelta(days=6)) + '); "next <weekday>" is in the following calendar week:']
        + wk + ['Calendar:'] + cal)

    _d = last_bd_of_week(monday_of(today)) if last_bd_of_week(monday_of(today)) > today else last_bd_of_week(monday_of(today) + datetime.timedelta(days=7))
    vars['attempt1_date'] = iso(_d)
    vars['attempt1_date_say'] = full(_d)
    cb_lines = []
    cb_days = []
    nowhm = now.strftime('%H:%M')
    cb_list = []
    try:
        cb_list.append(('TODAY', today))
    except Exception:
        pass
    try:
        cb_list.append(('THE NEXT BUSINESS DAY', nextbd(today)))
    except Exception:
        pass
    for label, dd in cb_list:
        start = '10:00'
        if dd == today:
            if nowhm >= '19:00':
                cb_lines.append('- ' + label + ' ' + full(dd) + ': no longer possible (it is ' + nowhm + ').')
                continue
            if nowhm > start:
                start = nowhm
            cb_lines.append('- ' + label + ' ' + full(dd) + ': any time LATER than ' + start + ' and no later than ' + '19:00' + '.')
        else:
            cb_lines.append('- ' + label + ' ' + full(dd) + ': any time from ' + '10:00' + ' to ' + '19:00' + ', both included.')
        cb_days.append(iso(dd))
    cb_lines.append('Any other day, or any time outside these windows, is NOT allowed.')
    tm = today + datetime.timedelta(days=1)
    cb_lines.append('"Tomorrow" is ' + full(tm) + (', which is allowed.' if iso(tm) in cb_days else ', which is NOT allowed.'))
    vars['callback_facts'] = '\n'.join(cb_lines)
    vars['code_state'] = 'ok'
except Exception as e:
    vars['date_facts'] = 'Date facts unavailable.'
    vars['callback_facts'] = 'Callback window unavailable.'
    vars['setup_state'] = 'error'
    vars['code_error'] = str(e)[:200]
if vars.get('code_state') == 'ok':
    vars['setup_state'] = 'ok'

